import { useCallback, useEffect, useRef, useState, createContext, useContext, lazy, Suspense } from 'react';
import MapCard from './MapCard';
import { QrScanner } from './QrScanner';
import { Link, Navigate, Route, Routes, useLocation, useNavigate, useParams } from 'react-router-dom';
import { Activity, AlertTriangle, Bell, Boxes, ChevronDown, CircleHelp, ClipboardList, HandHeart, LayoutDashboard, LogOut, MapPin, Menu, PackagePlus, Settings, ShieldCheck, Truck, Users, Utensils, X } from 'lucide-react';
const AdminAnalytics = lazy(() => import('./AdminAnalytics'));

type User={id:number;email:string;name:string;role:'DONOR'|'NGO'|'VOLUNTEER'|'ADMIN';verified:number;status:string};
type Session={user:User|null;csrf:string};
const SessionContext=createContext<{session:Session;refresh:()=>Promise<void>;toast:(s:string)=>void}>({session:{user:null,csrf:''},refresh:async()=>{},toast:()=>{}});
export function useSmart(){return useContext(SessionContext)}
export async function api(path:string,options:RequestInit={},csrf=''){const res=await fetch(path,{...options,credentials:'include',headers:{'Content-Type':'application/json',...(options.headers??{}),...(['POST','PUT','PATCH','DELETE'].includes(options.method??'')&&csrf?{'X-CSRF-Token':csrf}:{})}});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error??'Request failed');return data;}
const navByRole={DONOR:[['Overview','/',LayoutDashboard],['My donations','/donations',Boxes],['Create donation','/create',PackagePlus],['Impact','/impact',Activity],['Profile','/profile',Settings]],NGO:[['Overview','/',LayoutDashboard],['Find food','/donations',Utensils],['My claims','/claims',ClipboardList],['Requirements','/requirements',Boxes],['Demand forecast','/forecast',Activity],['Impact','/impact',HandHeart]],VOLUNTEER:[['Overview','/',LayoutDashboard],['Assignments','/assignments',Truck],['Delivery history','/history',ClipboardList],['Profile','/profile',Settings]],ADMIN:[['Overview','/',LayoutDashboard],['Users','/admin/users',Users],['NGO verification','/admin/ngos',ShieldCheck],['Donations','/donations',Boxes],['Audit log','/admin/audit',ClipboardList],['Settings','/admin/settings',Settings]]} as const;
function App(){const [session,setSession]=useState<Session>({user:null,csrf:''}),[toast,setToast]=useState('');const loc=useLocation();const navigate=useNavigate();const refresh=useCallback(async()=>{try{setSession(await api('/api/session'));}catch{setSession({user:null,csrf:''})}},[]);useEffect(()=>{void refresh()},[refresh]);useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),3200);return()=>clearTimeout(t)}},[toast]);const value={session,refresh,toast:(s:string)=>setToast(s)};return <SessionContext.Provider value={value}><div className="app-root"><Routes><Route path="/login" element={session.user?<Navigate to="/" replace/>:<AuthPage/>}/><Route path="/register" element={session.user?<Navigate to="/" replace/>:<AuthPage register/>}/><Route path="/" element={session.user?<Shell/>:<Landing/>}><Route index element={<Dashboard/>}/><Route path="donations/:id" element={<DonationDetail/>}/><Route path="donations" element={<Donations/>}/><Route path="create" element={<CreateDonation/>}/><Route path="claims" element={<MyClaims/>}/><Route path="requirements" element={<Requirements/>}/><Route path="assignments" element={<MyAssignments/>}/><Route path="history" element={<Coming title="Delivery history" text="Your completed rescue missions and impact."/>}/><Route path="impact" element={<Impact/>}/><Route path="forecast" element={<Forecast/>}/><Route path="profile" element={<Profile/>}/><Route path="admin/users" element={<AdminUsers/>}/><Route path="admin/ngos" element={<AdminNGOs/>}/><Route path="admin/audit" element={<AdminAudit/>}/><Route path="admin/settings" element={<AdminSettings/>}/><Route path="*" element={<Coming title="Page not found" text="This page is not available."/>}/></Route></Routes>{toast&&<div className="toast" role="status">{toast}</div>}<span className="route-key" aria-hidden="true">{loc.pathname}</span></div></SessionContext.Provider>}

function Brand({small=false}:{small?:boolean}){return <Link to="/" className={`brand ${small?'brand-small':''}`}><span className="brand-mark"><Utensils size={18}/></span><span>smartfood<span className="brand-dot">.</span></span></Link>}
function Landing(){const [stats,setStats]=useState<any>({});useEffect(()=>{void api('/api/summary').then(setStats).catch(()=>{})},[]);return <div className="landing"><header className="landing-nav"><Brand/><div className="nav-ctas"><Link className="nav-login" to="/login">Log in</Link><Link className="button button-primary" to="/register">Join the rescue <span>↗</span></Link></div></header><main><section className="hero"><div className="hero-copy"><div className="eyebrow"><span className="live-dot"/> CHENNAI FOOD RESCUE NETWORK</div><h1>Turn surplus food into <em>shared good.</em></h1><p className="hero-sub">A little extra can go a long way. SmartFood connects local kitchens with the communities that need a good meal.</p><div className="hero-actions"><Link className="button button-primary button-large" to="/register">Start rescuing food <span>↗</span></Link><Link className="button button-light button-large" to="/login">Explore dashboard</Link></div><div className="social-proof"><div className="avatar-stack"><i>M</i><i>A</i><i>R</i><i>+</i></div><span><b>Good food, good people.</b><br/>Made for Chennai communities</span></div></div><div className="hero-art"><div className="sun-shape"/><div className="food-orbit orbit-one"/><div className="food-orbit orbit-two"/><div className="meal-illustration"><span className="plate-leaf">✳</span><span className="plate-rice">〰</span><span className="plate-tomato">●</span><span className="plate-greens">❋</span></div><div className="float-card float-top"><span className="float-icon">🥗</span><span><b>Fresh meals</b><small>ready to share</small></span><span className="float-count">24</span></div><div className="float-card float-bottom"><span className="mini-check">✓</span><span><b>Rescue complete</b><small>Adyar · just now</small></span></div><div className="art-caption"><MapPin size={13}/> Chennai, Tamil Nadu</div></div></section><section className="impact-strip"><div><b>Every meal matters</b><span>Small acts, nourishing impact</span></div><div><strong>01</strong><span>Donors share surplus</span></div><div><strong>02</strong><span>NGOs claim what they need</span></div><div><strong>03</strong><span>Volunteers bring it home</span></div></section><div className="live-metrics"><div><strong>{stats.donations??0}</strong><span>donations shared</span></div><div><strong>{stats.meals??0}</strong><span>meals received</span></div><div><strong>{stats.partners??0}</strong><span>verified community NGOs</span></div><div><strong>{stats.volunteers??0}</strong><span>active volunteers</span></div></div><section className="how-section"><div className="section-kicker">GOOD FOOD SHOULD FIND A HOME</div><h2>Rescue made <em>simple.</em></h2><p>From one extra tray to a table full of smiles, every rescue moves with care.</p><div className="role-cards">{[['01','🍲','For food donors','Share safe, surplus food from your kitchen or event.'],['02','💚','For community NGOs','Find nearby food that fits your community’s needs.'],['03','🚲','For volunteers','Help get fresh food from pickup to people.']].map(x=><article className="role-card" key={x[0]}><span className="role-num">{x[0]}</span><span className="role-emoji">{x[1]}</span><h3>{x[2]}</h3><p>{x[3]}</p><Link to="/register">Get involved <span>↗</span></Link></article>)}</div></section><section className="faq-section"><div className="section-kicker">GOOD TO KNOW</div><h2>Questions, answered.</h2><details><summary>Does SmartFood certify food as safe?</summary><p>No. Donors and receiving organisations are responsible for checking food safety. Scores and suggestions never certify safety.</p></details><details><summary>Who can request a donation?</summary><p>Community NGOs can request food after an administrator approves their organisation application.</p></details><details><summary>How is impact estimated?</summary><p>Impact is counted only after an NGO confirms receipt. Food weight and emissions use adjustable estimate factors shown in the platform.</p></details></section><div className="safety-footer"><ShieldCheck size={17}/><span>Food safety must be verified by the donor and the receiving organisation.</span></div></main><footer className="landing-foot"><Brand small/><span>Good food has a place here.</span><span>© 2026 SmartFood · Chennai</span></footer></div>}

function AuthPage({register=false}:{register?:boolean}){const {refresh,toast}=useSmart();const [busy,setBusy]=useState(false);const nav=useNavigate();async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);const data=Object.fromEntries(new FormData(e.currentTarget));try{const out=await api(register?'/api/auth/register':'/api/auth/login',{method:'POST',body:JSON.stringify(data)});await refresh();toast(register&&out.pending?'Application submitted. Your NGO account is pending verification.':register?'Welcome to SmartFood.':'Welcome back.');nav('/');}catch(err){toast(err instanceof Error?err.message:'Please try again.')}finally{setBusy(false)}}return <div className="auth-screen"><div className="auth-aside"><Brand/><div><div className="eyebrow"><span className="live-dot"/> BETTER FOOD CIRCLES</div><h1>Good food.<br/><em>Better together.</em></h1><p>Join a local network turning surplus into nourishment, one rescue at a time.</p><div className="auth-note">“A shared meal is a small thing that changes a whole day.”<small>— The SmartFood community</small></div></div><span className="aside-bottom">Built for Chennai, with care.</span></div><div className="auth-panel"><Link to="/" className="back-link">← Back home</Link><div className="auth-box"><span className="section-kicker">{register?'YOUR COMMUNITY STARTS HERE':'WELCOME BACK'}</span><h2>{register?'Create your account':'Sign in to SmartFood'}</h2><p>{register?'Choose how you’d like to make a difference.':'Good to see you again. Let’s get food where it belongs.'}</p><form onSubmit={submit} className="form-stack">{register&&<label>Your name<input name="name" required minLength={2} maxLength={80} placeholder="e.g. Meera Krishnan"/></label>}<label>Email address<input name="email" type="email" required placeholder="you@example.com" autoComplete="email"/></label><label>Password<input name="password" type="password" required minLength={8} placeholder="At least 8 characters" autoComplete={register?'new-password':'current-password'}/></label>{register&&<label>Account type<select name="role" defaultValue="DONOR"><option value="DONOR">Food donor</option><option value="NGO">Community NGO</option><option value="VOLUNTEER">Volunteer</option></select></label>}<button className="button button-primary button-full" disabled={busy}>{busy?'Please wait…':register?'Create account':'Sign in'} <span>↗</span></button></form><div className="auth-switch">{register?'Already have an account?':'New to SmartFood?'} <Link to={register?'/login':'/register'}>{register?'Sign in':'Create an account'}</Link></div><div className="demo-hint"><b>Demo accounts</b><br/>admin@smartfood.demo · donor@smartfood.demo<br/>ngo@smartfood.demo · volunteer@smartfood.demo<br/><span>Password: Demo@12345</span></div></div></div></div>}

function Shell(){const {session,refresh,toast}=useSmart();const user=session.user!;const [mobile,setMobile]=useState(false),[notify,setNotify]=useState(false),[items,setItems]=useState<any[]>([]);const loc=useLocation();const navigate=useNavigate();const list=navByRole[user.role];useEffect(()=>{let active=true;const load=()=>api('/api/notifications').then(d=>{if(active)setItems(d)}).catch(()=>{});void load();const id=setInterval(load,30000);return()=>{active=false;clearInterval(id)}},[]);async function logout(){try{await api('/api/auth/logout',{method:'POST'},session.csrf)}finally{await refresh();navigate('/login');toast('You have signed out.')}}return <div className="workspace"><aside className={`sidebar ${mobile?'sidebar-open':''}`}><div className="sidebar-brand"><Brand/><button className="icon-button mobile-close" onClick={()=>setMobile(false)} aria-label="Close menu"><X size={19}/></button></div><div className="workspace-label">WORKSPACE</div><div className="account-card"><div className="account-avatar">{user.name[0]}</div><span><b>{user.name}</b><small>{user.role==='NGO'&&!user.verified?'Verification pending':roleLabel(user.role)}</small></span><ChevronDown size={15}/></div><nav className="side-nav" aria-label="Main navigation">{list.map(([label,to,Icon])=><Link key={to} onClick={()=>setMobile(false)} to={to} className={`side-link ${(loc.pathname===to||(to!=='/'&&loc.pathname.startsWith(to)))?'side-link-active':''}`}><Icon size={17}/><span>{label}</span>{to==='/admin/ngos'&&user.role==='ADMIN'&&<i className="nav-badge">2</i>}</Link>)}</nav><div className="sidebar-bottom"><div className="safety-mini"><ShieldCheck size={16}/><p>Food safety belongs to all of us.</p></div><button className="side-link signout" onClick={()=>void logout()}><LogOut size={17}/><span>Sign out</span></button><div className="sidebar-profile"><div className="profile-avatar">{user.name[0]}</div><span><b>{user.name}</b><small>{user.email}</small></span><button className="icon-button" onClick={()=>navigate('/profile')} aria-label="Open profile"><Settings size={16}/></button></div></div></aside>{mobile&&<button className="mobile-scrim" onClick={()=>setMobile(false)} aria-label="Close navigation"/>}<main className="main-area"><header className="topbar"><button className="icon-button menu-button" onClick={()=>setMobile(true)} aria-label="Open menu"><Menu size={20}/></button><div className="breadcrumbs">SmartFood <span>/</span> <b>{list.find(x=>x[1]===loc.pathname)?.[0]??'Overview'}</b></div><div className="topbar-actions"><button className={`icon-button notification-button ${notify?'is-open':''}`} onClick={()=>setNotify(!notify)} aria-label="Notifications"><Bell size={18}/>{items.filter(n=>!n.read_at).length>0&&<span className="notification-count">{items.filter(n=>!n.read_at).length}</span>}</button><div className="topbar-divider"/><div className="topbar-person"><div className="profile-avatar">{user.name[0]}</div><span><b>{user.name.split(' ')[0]}</b><small>{roleLabel(user.role)}</small></span></div></div>{notify&&<div className="notification-pop"><div><b>Notifications</b><button onClick={async()=>{await api('/api/notifications/read-all',{method:'POST'},session.csrf);setItems(items.map(i=>({...i,read_at:'now'})))}}>Mark all read</button></div>{items.length?items.slice(0,6).map(n=><p key={n.id}>{n.link?<Link to={n.link} onClick={()=>setNotify(false)}>{n.title}</Link>:n.title}<small>{n.body}</small>{!n.read_at&&<button onClick={async()=>{await api(`/api/notifications/${n.id}/read`,{method:"POST"},session.csrf);setItems(items.map(x=>x.id===n.id?{...x,read_at:"now"}:x))}}>Mark read</button>}</p>):<p>You’re all caught up.<small>New rescue updates will show here.</small></p>}</div>}</header><div className="page-content"><RoutesOutlet/></div></main></div>}
import { Outlet as RoutesOutlet } from 'react-router-dom';
function roleLabel(role:string){return {DONOR:'Food donor',NGO:'Community NGO',VOLUNTEER:'Volunteer',ADMIN:'Platform admin'}[role]??role}
function fileToData(file:File):Promise<string>{return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>typeof reader.result==='string'?resolve(reader.result):reject(new Error('Could not read image.'));reader.onerror=()=>reject(new Error('Could not read image.'));reader.readAsDataURL(file);});}
function PageHeader({eyebrow,title,sub,action}:{eyebrow:string;title:string;sub:string;action?:React.ReactNode}){return <div className="page-header"><div><div className="section-kicker">{eyebrow}</div><h1>{title}</h1><p>{sub}</p></div>{action}</div>}
function ScoreRing({label,value}:{label:string;value:number}){return <div className="score-ring" style={{background:`conic-gradient(#16835f ${Math.max(0,Math.min(100,value))*3.6}deg, #eaf0ea 0)`}}><div><b>{Math.round(value)}</b><small>{label}</small></div></div>}
function Countdown({expiresAt}:{expiresAt:string}){const [now,setNow]=useState(Date.now());useEffect(()=>{const t=setInterval(()=>setNow(Date.now()),1000);return()=>clearInterval(t)},[]);const left=Math.max(0,Date.parse(expiresAt)-now),hours=Math.floor(left/3600000),minutes=Math.floor(left%3600000/60000),seconds=Math.floor(left%60000/1000);return <span className="countdown" role="timer">{left===0?'Expired':`${hours}h ${minutes}m ${seconds}s left`}</span>}
function Dashboard(){const {session}=useSmart();const role=session.user!.role;const [overview,setOverview]=useState<any>(null);useEffect(()=>{const path=role==='ADMIN'?'/api/admin/overview':'/api/summary';void api(path).then(setOverview).catch(()=>{})},[role]);const config={DONOR:['YOUR COMMUNITY IMPACT','Your surplus food is helping people.','A little extra from you can make a big difference.'],NGO:['FOOD FOR YOUR COMMUNITY','Find the food your community needs.','Browse nearby donations that match your active needs.'],VOLUNTEER:['RESCUE MISSIONS','Your next rescue mission.','Help carry good food to the people who need it.'],ADMIN:['PLATFORM OVERVIEW','Monitor the entire food rescue ecosystem.','A clear view of what is happening across the network.']}[role];return <><PageHeader eyebrow={config[0]} title={config[1]} sub={config[2]} action={role==='DONOR'?<Link className="button button-primary" to="/create"><PackagePlus size={17}/> Add a donation</Link>:undefined}/>{role==='NGO'&&!session.user!.verified&&<div className="alert-banner"><ShieldCheck size={18}/><div><b>Your NGO verification is in review</b><p>You can explore listings while the team reviews your application. Claiming is available after approval.</p></div></div>}<div className="welcome-card"><div><div className="welcome-kicker">A COMMUNITY THAT CARES</div><h2>{role==='ADMIN'?'Every rescue starts with a connection.':'Good things happen when food finds its people.'}</h2><p>SmartFood brings generous kitchens and community organisations together, with local volunteers to help food travel safely.</p><Link to={role==='DONOR'?'/create':role==='NGO'?'/donations':role==='VOLUNTEER'?'/assignments':'/admin/users'}>{role==='DONOR'?'Share surplus food':role==='NGO'?'Find nearby food':role==='VOLUNTEER'?'View assignments':'Manage the network'} <span>↗</span></Link></div><div className="welcome-art"><div className="welcome-circle">🍲</div><span>made with<br/>care in Chennai</span></div></div><div className="stat-grid"><Stat icon={<Boxes/>} label={role==='ADMIN'?'Available donations':role==='DONOR'?'Your donations':'Available nearby'} value={role==='ADMIN'?overview?.available?.n??'—':role==='DONOR'?overview?.donations??'—':overview?.available??'—'} note="Across the SmartFood network" tone="green"/><Stat icon={<HandHeart/>} label="Food rescued (meals)" value={role==='ADMIN'?overview?.rescued??'—':overview?.meals??'—'} note="Confirmed receipt only" tone="amber"/><Stat icon={<Users/>} label={role==='ADMIN'?'Community members':'Active partners'} value={overview?.users?.n??'—'} note="Growing together" tone="blue"/><Stat icon={<Activity/>} label={role==='ADMIN'?'Pending NGO reviews':'Confirmed rescues'} value={role==='ADMIN'?overview?.pendingNgos?.n??'—':overview?.rescues??'—'} note={role==='ADMIN'?'Applications to review':'Ready for your next step'} tone="peach"/></div>{role==='ADMIN'&&<Suspense fallback={<div className="empty-card">Loading live analytics…</div>}><AdminAnalytics data={overview}/></Suspense>}<div className="section-row"><div><div className="section-kicker">YOUR NEXT STEP</div><h2>Make good things happen</h2></div><Link className="text-link" to="/donations">Explore donations <span>↗</span></Link></div><div className="action-grid">{(role==='DONOR'?[['🍱','Share a donation','Post safe surplus food in just a few steps.','/create','Create donation'],['🧭','Track your food','See requests and follow each rescue.','/donations','View donations'],['🌱','See your impact','Confirmed rescues add up to real change.','/impact','View impact']]:role==='NGO'?[['🥬','Find nearby food','Browse fresh donations and match to your needs.','/donations','Explore food'],['📋','Review your claims','Keep requests and deliveries in one place.','/claims','View claims'],['📈','Plan tomorrow','Use your demand history to look ahead.','/forecast','View forecast']]:role==='VOLUNTEER'?[['🚲','Check assignments','See nearby pickup and delivery opportunities.','/assignments','View assignments'],['🗺️','Plan your route','Know where each rescue is headed.','/assignments','Open routes'],['⭐','Your contribution','See your completed food rescue missions.','/history','View history']]:[['👥','Community accounts','Manage partners and platform access.','/admin/users','Manage users'],['🛡️','Verify NGOs','Review incoming community applications.','/admin/ngos','Review applications'],['📦','Food network','See all donations and active rescues.','/donations','View donations']]).map(x=><Link to={x[3]} className="action-card" key={x[1]}><span className="action-emoji">{x[0]}</span><h3>{x[1]}</h3><p>{x[2]}</p><span className="action-link">{x[4]} ↗</span></Link>)}</div><div className="dashboard-note"><CircleHelp size={17}/><span>SmartFood does not inspect or certify food. Donors and receiving organisations are responsible for verifying food safety.</span></div></>}
function Stat({icon,label,value,note,tone}:{icon:React.ReactNode;label:string;value:string|number;note:string;tone:string}){return <article className="stat-card"><div className={`stat-icon ${tone}`}>{icon}</div><span>{label}</span><strong>{value}</strong><small>{note}</small></article>}
function Donations(){const {session}=useSmart();const [data,setData]=useState<any>({items:[]});useEffect(()=>{void api(session.user?.role==='NGO'?'/api/recommendations':'/api/donations').then((x:any)=>setData(Array.isArray(x)?{items:x}:x)).catch(()=>{})},[session.user?.role]);const ngo=session.user?.role==='NGO';return <><PageHeader eyebrow={ngo?'NEARBY SURPLUS':'YOUR FOOD DONATIONS'} title={ngo?'Find food your community needs':'My donations'} sub={ngo?'Nearby options ranked against your active community requirements.':'Follow your donations and the communities they support.'} action={session.user?.role==='DONOR'?<Link to="/create" className="button button-primary"><PackagePlus size={16}/> New donation</Link>:undefined}/>{data.items.some((d:any)=>d.urgency?.band==='CRITICAL')&&<div className="emergency-banner"><AlertTriangle size={18}/><div><b>Emergency rescue · under two hours remaining</b><p>These donations need an immediate community response. Please check the countdown and pickup details.</p></div></div>}{data.items.length===0?<div className="empty-card"><span>🍃</span><h3>No donations yet</h3><p>When food is shared with the network, you’ll find it here.</p>{session.user?.role==='DONOR'&&<Link to="/create" className="button button-primary">Create your first donation</Link>}</div>:<div className="donation-grid">{data.items.map((d:any)=><article className="donation-card" key={d.id}><div className="donation-card-top"><span className="category-icon">{d.photo_path?<img className="food-thumb" src={`/api/uploads/${d.photo_path}`} alt="Food offered"/>:d.icon}</span><span className={`status-chip ${d.urgency?.band==='CRITICAL'?'status-red':d.urgency?.band==='VERY_HIGH'||d.urgency?.band==='HIGH'?'status-amber':d.status==='AVAILABLE'?'status-green':''}`}>{d.urgency?.band??d.status}</span></div><h3>{d.title}</h3><p>{d.description}</p><div className="donation-meta"><span>{d.category}</span><span>·</span><b>{d.available_quantity} {d.unit}s</b></div><div className="donation-score-rings"><ScoreRing label="Fresh" value={d.freshness??0}/><ScoreRing label="Urgent" value={d.urgency?.score??0}/><ScoreRing label="Priority" value={d.priority??0}/></div><div className="donation-location"><MapPin size={14}/>{d.address}{d.distanceKm!=null&&` · ${d.distanceKm} km`}</div>{ngo&&<div className="match-info"><b>{d.matchScore}% match</b><span>{d.matchExplanation}</span></div>}<div className="donation-foot"><small><Countdown expiresAt={d.expires_at}/></small><Link className="button button-small button-light" to={`/donations/${d.id}`}>Details ↗</Link></div></article>)}</div>}</>}
function CreateDonation(){
 const {session,toast}=useSmart();const [cats,setCats]=useState<any[]>([]),[busy,setBusy]=useState(false),[categoryId,setCategoryId]=useState(''),[suggestion,setSuggestion]=useState<any>(null);const nav=useNavigate();useEffect(()=>{void api('/api/categories').then(setCats).catch(()=>{})},[]);
 async function suggest(title:string){if(!title.trim())return;try{setSuggestion(await api('/api/classify',{method:'POST',body:JSON.stringify({title})},session.csrf))}catch(e){toast(String(e))}}
 async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);const f=new FormData(e.currentTarget);const photoFile=f.get('photo') as File;try{const photoData=photoFile?.size?await fileToData(photoFile):undefined;const now=new Date();const out={photoData,title:f.get('title'),description:f.get('description'),categoryId:Number(f.get('categoryId')),quantity:Number(f.get('quantity')),unit:f.get('unit'),preparedAt:f.get('preparedAt')?new Date(String(f.get('preparedAt'))).toISOString():new Date(now.getTime()-3600000).toISOString(),expiresAt:new Date(String(f.get('expiresAt'))).toISOString(),address:f.get('address'),lat:Number(f.get('lat')),lng:Number(f.get('lng')),safetyAck:f.get('safetyAck')==='on',items:[{name:String(f.get('title')),quantity:Number(f.get('quantity')),unit:f.get('unit')}]};await api('/api/donations',{method:'POST',body:JSON.stringify(out)},session.csrf);toast('Donation published to the network.');nav('/donations')}catch(err){toast(err instanceof Error?err.message:'Please check your details.')}finally{setBusy(false)}}
 return <><PageHeader eyebrow="SHARE SOME GOOD" title="Create a donation" sub="Tell the community what’s available and when it needs to be collected."/><div className="form-progress"><span>1 · Food</span><i/><span>2 · Pickup details</span><i/><span>3 · Safety confirmation</span></div><form className="editor-card" onSubmit={submit}><div className="form-section"><div className="form-step">01</div><div><h2>What are you sharing?</h2><p>Give your donation a clear, friendly description.</p></div></div><label>Donation title<input name="title" required minLength={3} placeholder="e.g. Fresh lunch packs" onBlur={e=>void suggest(e.target.value)}/></label>{suggestion&&<div className="suggestion-box"><span>{suggestion.notice} {suggestion.basis}</span><button type="button" className="button button-light button-small" onClick={()=>setCategoryId(String(suggestion.categoryId))}>Use {suggestion.category}</button></div>}<label>Description<textarea name="description" rows={3} placeholder="What’s included? Add any helpful details."/></label><label>Optional food photograph<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"/></label><div className="field-row"><label>Food category<select name="categoryId" required value={categoryId} onChange={e=>setCategoryId(e.target.value)}><option value="" disabled>Select a category</option>{cats.map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select></label><label>Quantity<input name="quantity" type="number" required min="0.1" step="0.1" placeholder="24"/></label><label>Unit<input name="unit" required defaultValue="meal"/></label></div><div className="form-section form-section-spaced"><div className="form-step">02</div><div><h2>Pickup and timing</h2><p>Help volunteers plan a safe, timely collection.</p></div></div><label>Pickup address<input name="address" required placeholder="Street, neighbourhood, Chennai"/></label><div className="field-row"><label>Latitude<input name="lat" type="number" required step="any" min="-90" max="90" defaultValue="13.0418"/></label><label>Longitude<input name="lng" type="number" required step="any" min="-180" max="180" defaultValue="80.2341"/></label></div><div className="field-row"><label>Prepared at<input name="preparedAt" type="datetime-local"/></label><label>Expires at<input name="expiresAt" type="datetime-local" required min={new Date().toISOString().slice(0,16)}/></label></div><div className="safety-check"><input id="safetyAck" name="safetyAck" type="checkbox" required/><label htmlFor="safetyAck">I confirm this food was prepared and stored safely and is fit for redistribution. I understand SmartFood does not inspect or certify food.</label></div><button className="button button-primary" disabled={busy}>{busy?'Publishing…':'Publish donation'} <span>↗</span></button></form></>}
function AdminUsers(){const {session,toast}=useSmart();const [data,setData]=useState<any>({items:[],page:1,total:0});const [q,setQ]=useState('');const load=useCallback((page=1)=>api(`/api/admin/users?page=${page}&q=${encodeURIComponent(q)}`).then(setData).catch(e=>toast(e.message)),[q,toast]);useEffect(()=>{void load()},[load]);async function status(id:number,value:string){try{await api(`/api/admin/users/${id}/status`,{method:'POST',body:JSON.stringify({status:value})},session.csrf);toast(`Account ${value.toLowerCase()}.`);await load(data.page)}catch(e){toast(String(e))}}return <><PageHeader eyebrow="PLATFORM MANAGEMENT" title="Community members" sub="Search accounts, review verification and manage access."/><div className="table-card"><div className="table-heading"><b>All users</b><span>{data.total} accounts</span></div><div className="table-tools"><input aria-label="Search users" placeholder="Search name or email" value={q} onChange={e=>setQ(e.target.value)}/><button className="button button-light button-small" onClick={()=>void load(1)}>Search</button></div><div className="responsive-table"><table><thead><tr><th>MEMBER</th><th>ROLE</th><th>STATUS</th><th>VERIFICATION</th><th>ACTION</th></tr></thead><tbody>{data.items.map((u:any)=><tr key={u.id}><td><b>{u.name}</b><small>{u.email}</small></td><td>{roleLabel(u.role)}</td><td><span className={`status-chip ${u.status==='ACTIVE'?'status-green':'status-red'}`}>{u.status}</span></td><td>{u.role==='NGO'?(u.verified?'Verified':'Pending'):'—'}</td><td>{u.id!==session.user?.id&&<button className="button button-light button-small" onClick={()=>void status(u.id,u.status==='ACTIVE'?'SUSPENDED':'ACTIVE')}>{u.status==='ACTIVE'?'Suspend':'Activate'}</button>}</td></tr>)}</tbody></table></div><div className="table-heading"><button className="button button-light button-small" disabled={data.page<=1} onClick={()=>void load(data.page-1)}>Previous</button><span>Page {data.page} · {data.total} total</span><button className="button button-light button-small" disabled={data.page*data.limit>=data.total} onClick={()=>void load(data.page+1)}>Next</button></div></div></>}
function DonationDetail(){const {id}=useParams(),{session,toast}=useSmart();const [d,setD]=useState<any>(),[scores,setScores]=useState<any>(),[backup,setBackup]=useState<any>();useEffect(()=>{if(!id)return;void api(`/api/donations/${id}`).then(setD).catch(e=>toast(e.message));void api(`/api/donations/${id}/scores`).then(setScores).catch(()=>{});if(session.user?.role==='DONOR')void api(`/api/donations/${id}/pickup-code`).then(setBackup).catch(()=>{})},[id,session.user?.role]);if(!d)return <div className="empty-card">Loading donation…</div>;return <><PageHeader eyebrow="DONATION DETAILS" title={d.title} sub={`${d.address} · ${d.status}`}/><div className="detail-grid"><section className="editor-card"><div className="section-kicker">AVAILABLE FOOD</div><h2>{d.available_quantity} {d.unit}s · {d.category}</h2><p>{d.description}</p><div className="safety-check">Food safety must be verified by the donor and the receiving organisation.</div><div className="stat-grid compact-stats">{[['Freshness',scores?.freshness],['Urgency',scores?.urgency?.score],['Priority',scores?.priority]].map(([n,v])=><div className="stat-card" key={String(n)}><span>{n}</span><strong>{v??'—'}<small>/100</small></strong></div>)}</div>{session.user?.role==='NGO'&&<ClaimForm donationId={Number(id)} available={d.available_quantity} disabled={!session.user.verified||d.status!=='AVAILABLE'}/>}<h3>Food items</h3>{d.items?.map((x:any)=><p key={x.id}>{x.name} · {x.quantity} {x.unit}</p>)}</section><aside className="editor-card"><div className="section-kicker">RESCUE TIMELINE</div><div className="timeline">{d.timeline?.map((x:any)=><div key={x.id}><i/><b>{x.event_type.replaceAll('_',' ')}</b><small>{x.actor??'SmartFood'} · {new Date(x.created_at).toLocaleString()}</small><p>{x.details}</p></div>)}</div>{backup&&<div className="verification-panel"><b>Pickup verification</b><p>Share this backup code with the assigned volunteer only.</p><img className="qr-image" src={backup.qrDataUrl} alt="Pickup verification QR code"/><code>{backup.code}</code><small>Expires {new Date(backup.expiresAt).toLocaleString()}</small></div>}</aside></div></>}
function ClaimForm({donationId,available,disabled=false}:{donationId:number;available:number;disabled?:boolean}){const {session,toast}=useSmart();const [quantity,setQuantity]=useState('');const [busy,setBusy]=useState(false);return <form className="inline-action" onSubmit={async e=>{e.preventDefault();setBusy(true);try{await api('/api/claims',{method:'POST',body:JSON.stringify({donationId,quantity:Number(quantity)})},session.csrf);toast('Your claim request was sent to the donor.');setQuantity('')}catch(err){toast(err instanceof Error?err.message:'Request failed.')}finally{setBusy(false)}}}><label>Request quantity<input type="number" min="0.1" step="0.1" max={available} required value={quantity} onChange={e=>setQuantity(e.target.value)}/></label><p>Food safety must be verified by the donor and the receiving organisation.</p><button className="button button-primary" disabled={disabled||busy}>{!session.user?.verified?'Verification required':busy?'Sending…':'Request food'}</button></form>}
function MyClaims(){
 const {session,toast}=useSmart();const [items,setItems]=useState<any[]>([]),[deliveryCodes,setDeliveryCodes]=useState<Record<number,any>>({});const load=useCallback(()=>api('/api/claims').then(setItems).catch(e=>toast(e.message)),[toast]);useEffect(()=>{void load()},[load]);const donor=session.user?.role==='DONOR';
 async function decide(id:number,decision:'APPROVED'|'REJECTED'){try{await api(`/api/claims/${id}/decision`,{method:'POST',body:JSON.stringify({decision,reason:decision==='REJECTED'?'Unable to fulfil this request.':undefined})},session.csrf);toast(decision==='APPROVED'?'Claim approved; a volunteer was offered the rescue.':'Claim declined.');await load()}catch(e){toast(String(e))}}
 async function showDeliveryCode(assignmentId:number){try{setDeliveryCodes({...deliveryCodes,[assignmentId]:await api(`/api/assignments/${assignmentId}/delivery-code`)})}catch(e){toast(String(e))}}
 return <><PageHeader eyebrow={donor?'DONOR APPROVALS':'YOUR REQUESTS'} title={donor?'Claims awaiting your decision':'My food claims'} sub={donor?'Approve claims to reserve quantities and offer a rescue assignment.':'Track requests and confirm deliveries when they arrive.'}/><div className="claim-list">{items.length?items.map(c=><article className="claim-row claim-row-wrap" key={c.id}><div><b>{c.title}</b><p>{c.ngo_name} · {c.quantity} {c.unit} · {c.status}</p>{c.reason&&<small>{c.reason}</small>}{!donor&&c.donation_status==='IN_TRANSIT'&&c.assignment_id&&<div><button className="button button-light button-small" onClick={()=>void showDeliveryCode(c.assignment_id)}>Show arrival verification</button>{deliveryCodes[c.assignment_id]&&<div className="verification-panel"><b>Receiving organisation arrival code</b><img className="qr-image" src={deliveryCodes[c.assignment_id].qrDataUrl} alt="Delivery verification QR code"/><code>{deliveryCodes[c.assignment_id].code}</code><small>Share this with the assigned volunteer. Expires {new Date(deliveryCodes[c.assignment_id].expiresAt).toLocaleString()}</small></div>}</div>}</div>{donor&&c.status==='PENDING'&&<div className="button-row"><button className="button button-primary" onClick={()=>void decide(c.id,'APPROVED')}>Approve</button><button className="button button-light" onClick={()=>void decide(c.id,'REJECTED')}>Decline</button></div>}{!donor&&c.status==='APPROVED'&&c.donation_status==='DELIVERED'&&<form className="inline-action receipt-form" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api(`/api/donations/${c.donation_id}/receipt`,{method:'POST',body:JSON.stringify({receivedQuantity:Number(f.get('receivedQuantity')),receivedBy:f.get('receivedBy'),safetyAck:f.get('safetyAck')==='on'})},session.csrf);toast('Receipt confirmed. Estimated impact updated.');await load()}catch(err){toast(String(err))}}}><label>Received quantity<input name="receivedQuantity" type="number" min="0.1" step="0.1" max={c.quantity} defaultValue={c.quantity} required/></label><label>Received by<input name="receivedBy" required/></label><label className="safety-check"><input name="safetyAck" type="checkbox" required/>I inspected the food on receipt and accept it for distribution.</label><button className="button button-primary">Confirm receipt</button></form>}{!donor&&c.status==='APPROVED'&&c.donation_status!=='DELIVERED'&&<Link className="button button-light" to={`/donations/${c.donation_id}`}>Open rescue</Link>}</article>):<div className="empty-card"><span>📋</span><h3>No claims yet</h3><p>Food requests and their progress will appear here.</p><Link to="/donations" className="button button-primary">Browse donations</Link></div>}</div></>}
function MyAssignments(){const {session,toast}=useSmart();const [items,setItems]=useState<any[]>([]),[codes,setCodes]=useState<Record<number,string>>({}),[proof,setProof]=useState<Record<number,{quantity:string;recipient:string}>>({});const reload=useCallback(()=>api('/api/assignments').then(setItems).catch(e=>toast(e.message)),[toast]);useEffect(()=>{void reload()},[reload]);async function act(id:number,path:string,body:unknown={}){try{await api(`/api/assignments/${id}/${path}`,{method:'POST',body:JSON.stringify(body)},session.csrf);toast('Rescue mission updated.');await reload()}catch(e){toast(e instanceof Error?e.message:'Action failed.')}}return <><PageHeader eyebrow="RESCUE MISSIONS" title="Your next rescue mission." sub="Accept a nearby offer, verify each handoff, and record the delivery."/><div className="claim-list">{items.length?items.map(a=><article className="assignment-card" key={a.id}><div className="assignment-head"><div><span className="status-chip status-green">{a.status}</span><h3>{a.title}</h3><p>{a.pickup_address} → {a.ngo_name}, {a.ngo_address}</p><small>{a.quantity} portions · expires {new Date(a.expires_at).toLocaleString()}</small></div></div><MapCard donorLat={a.pickup_lat} donorLng={a.pickup_lng} ngoLat={a.ngo_lat} ngoLng={a.ngo_lng} donorAddress={a.pickup_address} ngoAddress={a.ngo_address}/>{a.status==='OFFERED'&&<div className="button-row"><button className="button button-primary" onClick={()=>void act(a.id,'respond',{accept:true})}>Accept mission</button><button className="button button-light" onClick={()=>void act(a.id,'respond',{accept:false})}>Decline</button></div>}{a.status==='ACCEPTED'&&<button className="button button-primary" onClick={()=>void act(a.id,'pickup/start')}>Start pickup</button>}{a.status==='PICKUP_STARTED'&&<div className="inline-action"><label>Donor pickup code<input value={codes[a.id]??''} maxLength={100} onChange={e=>setCodes({...codes,[a.id]:e.target.value})} placeholder="8-digit code or QR token"/></label><p>Food safety must be verified by the donor and the receiving organisation.</p><QrScanner onCode={code=>setCodes({...codes,[a.id]:code})}/><button className="button button-primary" onClick={()=>void act(a.id,'verify',{stage:'PICKUP',value:codes[a.id]})}>Verify pickup</button></div>}{a.status==='PICKED_UP'&&<button className="button button-primary" onClick={()=>void act(a.id,'delivery/start')}>Start delivery</button>}{a.status==='IN_TRANSIT'&&<div className="inline-action"><label>NGO arrival code<input value={codes[a.id]??''} maxLength={100} onChange={e=>setCodes({...codes,[a.id]:e.target.value})} placeholder="Ask the receiving NGO"/></label><QrScanner onCode={code=>setCodes({...codes,[a.id]:code})}/><button className="button button-primary" onClick={()=>void act(a.id,'verify',{stage:'DELIVERY',value:codes[a.id]})}>Verify arrival</button></div>}{a.status==='DELIVERED'&&<div className="inline-action"><label>Delivered quantity<input type="number" min="0.1" step="0.1" value={proof[a.id]?.quantity??a.quantity} onChange={e=>setProof({...proof,[a.id]:{quantity:e.target.value,recipient:proof[a.id]?.recipient??''}})}/></label><label>Recipient name<input value={proof[a.id]?.recipient??''} onChange={e=>setProof({...proof,[a.id]:{quantity:proof[a.id]?.quantity??String(a.quantity),recipient:e.target.value}})}/></label><button className="button button-primary" onClick={()=>void act(a.id,'delivery',{deliveredQuantity:Number(proof[a.id]?.quantity??a.quantity),recipientName:proof[a.id]?.recipient??session.user?.name})}>Submit delivery proof</button></div>}</article>):<div className="empty-card"><span>🚲</span><h3>No assignment offers</h3><p>New nearby rescue opportunities will appear here.</p></div>}</div></>}
function Requirements(){const {session,toast}=useSmart();const [items,setItems]=useState<any[]>([]),[cats,setCats]=useState<any[]>([]);const load=useCallback(()=>api('/api/requirements').then(setItems).catch(e=>toast(e.message)),[toast]);useEffect(()=>{void load();void api('/api/categories').then(setCats).catch(()=>{})},[load]);return <><PageHeader eyebrow="COMMUNITY NEEDS" title="Food requirements" sub="Share what your community needs to guide donation matching."/><form className="inline-action requirement-form" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/requirements',{method:'POST',body:JSON.stringify({categoryId:Number(f.get('categoryId')),quantity:Number(f.get('quantity')),priority:Number(f.get('priority')),details:f.get('details')})},session.csrf);toast('Requirement saved.');e.currentTarget.reset();await load()}catch(err){toast(String(err))}}}><label>Category<select name="categoryId" required>{cats.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Quantity<input name="quantity" type="number" min="1" required/></label><label>Priority<select name="priority" defaultValue="3">{[1,2,3,4,5].map(n=><option value={n} key={n}>{n}</option>)}</select></label><label>Notes<input name="details" maxLength={300}/></label><button className="button button-primary">Add requirement</button></form><div className="claim-list">{items.map(x=><article className="claim-row" key={x.id}><div><b>{x.category} · {x.quantity} needed</b><p>{x.details} · Priority {x.priority}/5</p></div><button className="button button-light" onClick={async()=>{await api(`/api/requirements/${x.id}`,{method:'DELETE'},session.csrf);await load()}}>Remove</button></article>)}</div></>}
function Impact(){const [data,setData]=useState<any>();useEffect(()=>{void api('/api/impact').then(setData).catch(()=>{})},[]);return <><PageHeader eyebrow="ESTIMATED IMPACT" title="Good food, shared further." sub="Calculated from confirmed receipts and editable platform factors."/><div className="stat-grid">{[['Food rescued',`${data?.foodKg??'—'} kg`],['Meals redistributed',data?.meals??'—'],['People served',data?.peopleServed??'—'],['CO₂ avoided',`${data?.co2Kg??'—'} kg`]].map(x=><Stat key={String(x[0])} icon={<HandHeart/>} label={String(x[0])} value={x[1] as string} note="ESTIMATED IMPACT" tone="green"/>)}</div><div className="dashboard-note">Assumption: each received meal represents one serving; food weight is estimated at 0.4 kg per meal and emissions at 2.5 kg CO₂ per kg food.</div></>}
function Forecast(){const [rows,setRows]=useState<any[]>([]);useEffect(()=>{void api('/api/forecast').then(setRows).catch(()=>{})},[]);return <><PageHeader eyebrow="DEMAND PLANNING" title="Tomorrow’s community needs" sub="Averages from recorded demand for the same weekday in previous weeks."/><div className="claim-list">{rows.map(x=><article className="claim-row" key={x.category}><b>{x.category}</b><span>{x.forecast===null?'Not enough data.':`${x.forecast} portions · ${x.samples} matching days`}</span></article>)}</div></>}
function Profile(){const {session,toast}=useSmart();const [u,setU]=useState<any>(session.user);useEffect(()=>{void api('/api/profile').then(setU).catch(()=>{})},[]);return <><PageHeader eyebrow="ACCOUNT SETTINGS" title="Your profile" sub="Keep your account information current for your community."/><form className="editor-card" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/profile',{method:'PATCH',body:JSON.stringify({name:f.get('name'),address:f.get('address'),lat:Number(f.get('lat')),lng:Number(f.get('lng')),capacity:Number(f.get('capacity')),available:f.get('available')==='on'})},session.csrf);toast('Profile updated.')}catch(err){toast(String(err))}}}><label>Name<input name="name" defaultValue={u?.name}/></label><label>Email<input value={u?.email??''} readOnly/></label><label>Address<input name="address" defaultValue={u?.address??''}/></label><div className="field-row"><label>Latitude<input name="lat" type="number" step="any" defaultValue={u?.lat??13.0418}/></label><label>Longitude<input name="lng" type="number" step="any" defaultValue={u?.lng??80.2341}/></label></div>{u?.role==='VOLUNTEER'&&<><label>Vehicle capacity<input name="capacity" type="number" defaultValue={u.capacity}/></label><label className="safety-check"><input name="available" type="checkbox" defaultChecked={Boolean(u.available)}/>Available for rescue assignments</label></>}<button className="button button-primary">Save profile</button></form></>}
function AdminNGOs(){const {session,toast}=useSmart();const [items,setItems]=useState<any[]>([]);const load=useCallback(()=>api('/api/admin/ngos').then(setItems).catch(e=>toast(e.message)),[toast]);useEffect(()=>{void load()},[load]);return <><PageHeader eyebrow="VERIFICATION QUEUE" title="NGO applications" sub="Review organisations before they can request food."/><div className="claim-list">{items.map(x=><article className="claim-row" key={x.id}><div><b>{x.name}</b><p>{x.email} · {x.address}</p></div><div className="button-row"><button className="button button-primary" onClick={async()=>{await api(`/api/admin/ngos/${x.id}/decision`,{method:'POST',body:JSON.stringify({decision:'APPROVED'})},session.csrf);await load()}}>Approve</button><button className="button button-light" onClick={async()=>{const reason=window.prompt('Required rejection reason');if(!reason)return;await api(`/api/admin/ngos/${x.id}/decision`,{method:'POST',body:JSON.stringify({decision:'REJECTED',reason})},session.csrf);await load()}}>Reject</button></div></article>)}</div></>}
function AdminSettings(){const {session,toast}=useSmart();const [cats,setCats]=useState<any[]>([]),[factors,setFactors]=useState<any[]>([]);const load=useCallback(async()=>{try{setCats(await api('/api/categories'));setFactors(await api('/api/admin/settings'))}catch(e){toast(String(e))}},[toast]);useEffect(()=>{void load()},[load]);async function add(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/admin/categories',{method:'POST',body:JSON.stringify({name:f.get('name'),icon:f.get('icon')||'🍲'})},session.csrf);toast('Category added.');e.currentTarget.reset();await load()}catch(e){toast(String(e))}}async function save(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/admin/settings',{method:'PATCH',body:JSON.stringify({kg_per_meal:Number(f.get('kg')),co2_kg_per_kg:Number(f.get('co2'))})},session.csrf);toast('Impact factors updated.');await load()}catch(e){toast(String(e))}}const factor=(k:string)=>factors.find(x=>x.key===k)?.value;return <><PageHeader eyebrow="PLATFORM SETTINGS" title="Categories and impact factors" sub="Maintain food categories and transparent estimate assumptions."/><div className="detail-grid"><section className="editor-card"><h2>Food categories</h2><form className="inline-action" onSubmit={add}><label>Category name<input name="name" required maxLength={60}/></label><label>Icon<input name="icon" maxLength={12} placeholder="🍲"/></label><button className="button button-primary">Add category</button></form>{cats.map(c=><article className="claim-row" key={c.id}><b>{c.icon} {c.name}</b><button className="button button-light button-small" onClick={async()=>{if(!window.confirm(`Remove ${c.name}?`))return;try{await api(`/api/admin/categories/${c.id}`,{method:'DELETE'},session.csrf);await load()}catch(e){toast(String(e))}}}>Remove</button></article>)}</section><section className="editor-card"><h2>Estimated impact assumptions</h2><p>Applied only to confirmed receipt quantities.</p><form className="form-stack" onSubmit={save}><label>Estimated kg of food per meal<input name="kg" type="number" min="0.01" max="5" step="0.01" defaultValue={factor('kg_per_meal')??0.4}/></label><label>kg CO₂ avoided per kg of food<input name="co2" type="number" min="0.01" max="20" step="0.01" defaultValue={factor('co2_kg_per_kg')??2.5}/></label><button className="button button-primary">Save factors</button></form></section></div></>}
function AdminAudit(){const [data,setData]=useState<any>({items:[]});useEffect(()=>{void api('/api/admin/audit').then(setData).catch(()=>{})},[]);return <><PageHeader eyebrow="PLATFORM OVERSIGHT" title="Audit log" sub="Important platform changes and rescue events."/><div className="table-card"><div className="responsive-table"><table><thead><tr><th>TIME</th><th>ACTOR</th><th>EVENT</th><th>DETAILS</th></tr></thead><tbody>{data.items.map((x:any)=><tr key={x.id}><td>{new Date(x.created_at).toLocaleString()}</td><td>{x.actor??'System'}</td><td>{x.action}</td><td>{x.details}</td></tr>)}</tbody></table></div></div></>}

function Coming({title,text}:{title:string;text:string}){return <><PageHeader eyebrow="SMARTFOOD WORKSPACE" title={title} sub={text}/><div className="empty-card"><span>🌿</span><h3>Built around real community needs</h3><p>This workspace is taking shape. Your account and rescue network are ready.</p></div></>}
export default App;
